def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    H, W = g.shape
    mark = 2
    for o in objects(g, bg=bg):
        y0, x0, y1, x1 = o["box"]
        h, w = y1 - y0 + 1, x1 - x0 + 1
        if h != w or h < 2:
            continue  # only square objects of side >= 2 get decorated
        for (cy, cx, dy, dx) in [(y0, x0, -1, -1), (y0, x1, -1, 1),
                                 (y1, x0, 1, -1), (y1, x1, 1, 1)]:
            for (ny, nx) in [(cy + dy, cx), (cy, cx + dx)]:
                if 0 <= ny < H and 0 <= nx < W and out[ny, nx] == bg:
                    out[ny, nx] = mark
        emit(out.copy(), f"Square object with bbox {o['box']} (side {h}): paint colour 2 on the two outside orthogonal neighbours of each of its four corners")
    emit(out.copy(), "All square objects decorated; non-square objects left untouched")
    return out
